{"code":"import pandas as pd
import numpy as np

raw = pd.read_csv('raw_responses.csv')
out = pd.read_csv('pipeline_output.csv')

# Let's write a python scorer and compare column by column

def score_phq9(row):
    items = [row[f'phq9_{i}'] for i in range(1, 10)]
    # Check missing (-9 or outside 0..3)
    valid_items = [x for x in items if x in [0, 1, 2, 3]]
    n_missing = len(items) - len(valid_items)

    if n_missing >= 2:
        total = np.nan
        band = np.nan
        prorated = np.nan
    elif n_missing == 1:
        # scale up
        s = sum(valid_items)
        # multiply by full n (9), divide by actually answered (8), round, halves round up
        # formula: round(s * 9 / 8) with rounding half up. python round() does round-to-even.
        from decimal import Decimal, ROUND_HALF_UP
        val = Decimal(str(s)) * Decimal('9') / Decimal('8')
        total = int(val.quantize(Decimal('1'), rounding=ROUND_HALF_UP))
        prorated = True
    else:
        total = sum(items)
        prorated = False

    if pd.isna(total):
        band = np.nan
    else:
        if total <= 4:
            band = 'none-minimal'
        elif total <= 9:
            band = 'mild'
        elif total <= 14:
            band = 'moderate'
        elif total <= 19:
            band = 'moderately severe'
        else:
            band = 'severe'

    # self harm flag: q9 in [1, 2, 3] -> True, 0 -> False, missing -> nan
    q9 = row['phq9_9']
    if q9 in [1, 2, 3]:
        sh_flag = True
    elif q9 == 0:
        sh_flag = False
    else:
        sh_flag = np.nan

    return pd.Series({
        'phq9_total': total,
        'phq9_band': band,
        'phq9_prorated': prorated,
        'phq9_self_harm_flag': sh_flag
    })

def score_gad7(row):
    items = [row[f'gad7_{i}'] for i in range(1, 8)]
    valid_items = [x for x in items if x in [0, 1, 2, 3]]
    n_missing = len(items) - len(valid_items)

    if n_missing >= 2:
        total = np.nan
        band = np.nan
        prorated = np.nan
    elif n_missing == 1:
        s = sum(valid_items)
        from decimal import Decimal, ROUND_HALF_UP
        val = Decimal(str(s)) * Decimal('7') / Decimal('6')
        total = int(val.quantize(Decimal('1'), rounding=ROUND_HALF_UP))
        prorated = True
    else:
        total = sum(items)
        prorated = False

    if pd.isna(total):
        band = np.nan
    else:
        if total <= 4:
            band = 'minimal'
        elif total <= 9:
            band = 'mild'
        elif total <= 14:
            band = 'moderate'
        else:
            band = 'severe'

    return pd.Series({
        'gad7_total': total,
        'gad7_band': band,
        'gad7_prorated': prorated
    })

def score_rses(row):
    items = []
    for i in range(1, 11):
        val = row[f'rses_{i}']
        if val in [0, 1, 2, 3]:
            if i in [3, 5, 8, 9, 10]:
                items.append(3 - val)
            else:
                items.append(val)
        else:
            items.append(-999) # missing marker

    valid_items = [x for x in items if x != -999]
    n_missing = len(items) - len(valid_items)

    if n_missing >= 2:
        total = np.nan
        prorated = np.nan
    elif n_missing == 1:
        s = sum(valid_items)
        from decimal import Decimal, ROUND_HALF_UP
        val = Decimal(str(s)) * Decimal('10') / Decimal('9')
        total = int(val.quantize(Decimal('1'), rounding=ROUND_HALF_UP))
        prorated = True
    else:
        total = sum(items)
        prorated = False

    return pd.Series({
        'rses_total': total,
        'rses_prorated': prorated
    })

res_list = []
for idx, row in raw.iterrows():
    p = score_phq9(row)
    g = score_gad7(row)
    r = score_rses(row)
    combined = pd.concat([pd.Series({'respondent_id': row['respondent_id']}), p, g, r])
    res_list.append(combined)

my_out = pd.DataFrame(res_list)

# Compare with out
for col in out.columns:
    if col == 'respondent_id':
        continue
    # compare values
    # handle bools and floats/strings/nans properly
    match = my_out[col].astype(str) == out[col].astype(str)
    mismatches = ~match
    n_mismatch = mismatches.sum()
    print(f"Column {col}: {n_mismatch} mismatches")
    if n_mismatch > 0:
        diffs = pd.DataFrame({'my': my_out[col], 'pipe': out[col], 'id': raw['respondent_id']})[mismatches]
        print(diffs.head(10))
